def gain(c,n,name,text,page=None,prof=None,**extra):
 g=dict(nivel=n,nome=name,descricao=text,automatico=bool(prof),fonte=F,pagina=page or c['pagina']+1,**extra)
 if prof:g['proficiencias']=prof
 c['progressao'].append(g)
def arms(c,n,rank,martial=True,bombs=False):
 data={'simples':rank,'desarmado':rank}
 if martial:data['marciais']=rank
 if bombs:data['bombasAlquimicas']=rank
 gain(c,n,'Armas '+{2:'Especialista',3:'Mestre'}[rank],'Proficiência nas armas indicadas aumenta para '+{2:'especialista',3:'mestre'}[rank]+'.',prof={'armas':data})
def armor(c,n,rank,groups):gain(c,n,'Defesa '+{2:'Especialista',3:'Mestre',4:'Lendária'}[rank],'Proficiência em '+', '.join({'sem':'defesa sem armadura','leve':'armadura leve','media':'armadura média','pesada':'armadura pesada'}[k] for k in groups)+' aumenta para '+{2:'especialista',3:'mestre',4:'lendário'}[rank]+'.',prof={'armaduras':{k:rank for k in groups}})
def saves(c,n,key,rank,name,extra=''):gain(c,n,name,'Proficiência em '+{'fortitude':'Fortitude','reflexos':'Reflexos','vontade':'Vontade'}[key]+' passa a '+{2:'especialista',3:'mestre',4:'lendário'}[rank]+'. '+extra,prof={'salvaguardas':{key:rank}})
def perception(c,n,rank):gain(c,n,'Percepção '+{2:'Especialista',3:'Mestre',4:'Lendária'}[rank],'Percepção passa a '+{2:'especialista',3:'mestre',4:'lendário'}[rank]+'.',prof={'percepcao':rank})
