gain(O,1,'Repertório Divino','Conjura espontaneamente com Carisma; repertório e espaços são separados. Truques/foco se elevam a metade do nível arredondada para cima. A tabela inicial concede três espaços de1ª graduação, mas a prosa diz dois; divergência da impressão registrada, sem correção silenciosa.',131);gain(O,1,'Maldição Oracular','Depois da habilidade ligada à maldição, ganha amaldiçoado1 ou aumenta valor em1. Limite inicial2; no limite não pode usar tais habilidades. Efeitos são cumulativos. Só Refocar reduz valor em1 e recupera1foco; efeitos não podem ser contornados por itens/magias.',133);gain(O,3,'Magias Assinatura','Escolhe uma por graduação disponível e pode elevar sem aprender versões separadas, inclusive usar versões inferiores se aprendeu elevada.',133);gain(O,7,'Conjurador Especialista','Ataques/CDs de magia passam a especialista.',134,{'conjuracao':2});saves(O,7,'vontade',3,'Determinação Misteriosa','Sucessos tornam-se críticos.');saves(O,9,'fortitude',2,'Fortitude Mágica');gain(O,11,'Acesso Divino','Escolhe divindade com domínio de seu mistério; adiciona até três magias concedidas por ela à lista e ao repertório quando puder conjurá-las.',134);gain(O,11,'Maldição Maior','Limite de amaldiçoado passa a3.',134);perception(O,11,2);arms(O,11,2,False);armor(O,13,2,['sem','leve']);saves(O,13,'reflexos',2,'Reflexos Premonitórios');spec(O,13);gain(O,15,'Conjurador Mestre','Ataques/CDs de magia passam a mestre.',135,{'conjuracao':3});gain(O,17,'Maldição Extrema','Limite passa a4.',135);saves(O,17,'vontade',4,'Determinação Misteriosa Maior','Sucessos tornam-se críticos; falha crítica vira falha; falha contra dano causa metade.');gain(O,19,'Conjurador Lendário','Ataques/CDs de magia passam a lendário.',135,{'conjuracao':4});gain(O,19,'Clareza Oracular','Aprende duas magias divinas comuns de10ª graduação e recebe um espaço especial para elas. Não cresce normalmente nem funciona com habilidades que dão espaços ou conjuram sem gastá-los.',135)
# Feiticeiro.
gain(S,1,'Repertório e Linhagem','Aprende quatro truques e duas magias de1ª graduação à escolha, mais um truque e uma magia de linhagem. Três espaços iniciais. A primeira nova magia de cada graduação é a da linhagem. A cada nível pode trocar uma magia não concedida pela linhagem por outra da mesma graduação. Linhagem concede duas perícias, uma magia de foco e1Ponto de Foco.',148);gain(S,1,'Potência Feiticeira','Magia de espaço que causa dano/restaura PV recebe bônus de estado igual à graduação na cura/dano inicial. Cada criatura recebe aumento uma vez por conjuração.',148);gain(S,1,'Magia Sanguínea','Após conjurar magia de foco da linhagem ou magia concedida pela linhagem usando espaço, escolhe um efeito conhecido de magia sanguínea. Normalmente apenas um. Outros efeitos exigem talentos.',150);gain(S,3,'Magias Assinatura','Escolhe uma por graduação; pode elevar livremente sem aprender versões separadas e usar versões menores de assinatura aprendida elevada.',149);saves(S,5,'fortitude',2,'Fortitude Mágica');gain(S,7,'Conjurador Especialista','Ataques/CDs de magia passam a especialista.',149,{'conjuracao':2});saves(S,9,'reflexos',2,'Reflexos Especialista');perception(S,11,2);arms(S,11,2,False);armor(S,13,2,['sem']);spec(S,13);gain(S,15,'Conjurador Mestre','Ataques/CDs de magia passam a mestre.',150,{'conjuracao':3});saves(S,17,'vontade',3,'Vontade Majestosa','Sucessos tornam-se críticos.');gain(S,19,'Conjurador Lendário','Ataques/CDs de magia passam a lendário.',150,{'conjuracao':4});gain(S,19,'Excelência da Linhagem','Aprende duas magias comuns de10ª graduação da tradição e recebe um espaço especial. Não cresce normalmente nem funciona com habilidades que dão espaços ou conjuram sem gastá-los.',150)
# Espadachim Remaster: dano preciso não exige panache.
gain(W,1,'Panache e Bravata','Atravessar e ações do estilo ganham bravata. Sucesso no teste concede panache; falha não crítica concede até fim do próximo turno, mesmo sem outro efeito por imunidade. Mestre pode permitir ações especialmente ousadas com teste significativo. Normalmente só em encontro; termina ao fim dele.',161);gain(W,1,'Golpe Preciso','Arma corpo a corpo/ataque desarmado ágil ou acuidade causa +2 precisão; finalização +2d6. Aumenta +1/+1d6 nos níveis5,9,13,17, até +6/+6d6.',161);gain(W,1,'Combatente Estiloso','Em encontro, +1 circunstância em bravata; com panache, +5 pés estado aos Deslocamentos.',161);gain(W,1,'Finalização Confiante','Uma ação, exige e consome panache. Golpe adequado para Golpe Preciso. Falha não crítica causa metade do dano de Golpe Preciso, do mesmo tipo da arma. Depois não usa ações de ataque no restante do turno.',162);saves(W,3,'fortitude',2,'Fortitude Especialista');gain(W,3,'Ripostar Oportuno','Reação quando inimigo ao alcance falha criticamente em Golpe contra você: Golpe corpo a corpo ou Desarmar sua arma. Tem bravata.',162)
for n in [3,7,15]:gain(W,n,'Truques Estilosos','Aumento de perícia extra e talento de perícia extra; ambos em Acrobacia ou perícia do estilo.',162)
gain(W,3,'Velocidade Vivaz','Bônus com panache passa a+10 pés estado, +5 nos níveis7,11,15,19. Sem panache recebe metade arredondada para baixo ao múltiplo de5 pés. Não soma bônus de estado.',162);arms(W,5,2);gain(W,5,'Especialização Crítica','Armas em que é especialista recebem especialização crítica.',162);saves(W,7,'reflexos',3,'Evasão Confiante','Sucessos tornam-se críticos.');spec(W,7);gain(W,9,'Finalização Exemplar','Dançarino: Passo livre; Fanfarrão: remove imunidade ao seu Desmoralizar; Esgrimista: desprevenido até próximo turno; Ginasta: dano circunstancial 2×dados da arma se alvo agarrado/restringido/prostrado; Malandro: −10 pés circunstância até próximo turno; Sagaz: −2 circunstância em ataques contra você até próximo turno.',163);gain(W,9,'Espadachim Especialista','CD passa a especialista e bônus de Combatente Estiloso a+2.',163,{'cdClasse':2});gain(W,11,'Estilo Contínuo','Bônus de Combatente Estiloso também em exploração.',163);perception(W,11,3);saves(W,13,'reflexos',4,'Evasão Assegurada','Falha crítica vira falha; falha contra dano causa metade.');armor(W,13,2,['sem','leve']);arms(W,13,3);spec(W,15,True);gain(W,15,'Estilo Aguçado','Em Golpe com arma/ataque em que é mestre,19 natural que seria sucesso vira crítico.',163);saves(W,17,'vontade',3,'Ego Reforçado','Sucessos tornam-se críticos.');gain(W,19,'Confiança Eterna','CD passa a mestre. Finalização/Ripostar pode receber efeito de falha de Finalização Confiante, inclusive Finalização Precisa se possuir, apenas com arma/ataque adequado.',163,{'cdClasse':3});armor(W,19,3,['sem','leve'])
